with a as(select * from public.authors where open_library_id=any(array['OL25712A','OL2675573A','OL76437A','OL587370A','OL8270388A','OL9732436A','OL9911149A']::text[])),w as(select * from public.works where open_library_id=any(array['OL30816328W','OL36883768W','OL34311013W','OL34836395W','OL15367338W','OL453737W','OL872773W']::text[])) select jsonb_build_object('checked_at',clock_timestamp(),'project','hlvujbrmfdlrfxdjwsmb','authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'works',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from w t),'editions',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where work_id in(select id from w) or isbn_13=any(array['9789025451400','9789021475899','9789029093606','9789048816743','9789035131873','9780593058299','9789022543122','9789023411239']::text[]) or open_library_edition_id=any(array['OL42340979M','OL49819445M','OL46531106M','OL47190548M','OL24732287M','OL27041696M','OL27307064M','OL24897730M']::text[])),'reserved_range',jsonb_build_object('works',(select count(*) from public.works where id between 987113001 and 987113999),'editions',(select count(*) from public.editions where id between 987213001 and 987213999),'authors',(select count(*) from public.authors where id between 987313001 and 987313999))) as preflight;
